import {ancestryTools,ancestryEditor,wireAncestry} from './ancestry.js?v=0.17.0';
import {hasDescendants,assertPortable} from '../shared/ancestry.js?v=0.17.0';
import {mountShell} from '../shared/shell.js?v=0.17.0';
import {escapeHtml as e,downloadText,writeStore} from '../shared/utils.js?v=0.17.0';
import {PRESETS,uid,createWorkspace,ingredients,combinationCount,mixWorkspace,captureConcept,markdown,validateWorkspace} from './model.js?v=0.17.0';
import {navigation,mapView,fitEditor,sourceRecord,wireCoverage} from './coverage.js?v=0.17.0';
import {gap,noteKey} from './map.js?v=0.17.0';
import {parseImport} from './import.js?v=0.17.0';
mountShell({active:'mixer'});
const KEY='thinking-lab:mixer:v1';
let state,undo=[],promptIndex=0,toastTimer,recoveryRaw=null,savePaused=false,storageNotice='';
let raw=null;try{raw=localStorage.getItem(KEY);}catch{storageNotice='Browser storage is unavailable. Export your work to keep it.';}
try{if(!raw)throw Error();state=JSON.parse(raw);if(!Array.isArray(state?.workspaces)||!state.workspaces.length||state.workspaces.length>100)throw Error();state.workspaces=state.workspaces.map(validateWorkspace);if(new Set(state.workspaces.map(w=>w.id)).size!==state.workspaces.length)throw Error();if(!state.workspaces.some(w=>w.id===state.activeId))state.activeId=state.workspaces[0].id;}catch{if(raw){recoveryRaw=raw;savePaused=true;storageNotice='Saved data could not be read. Saving is paused to preserve it. Download a recovery copy before starting fresh.';}const w=createWorkspace();state={workspaces:[w],activeId:w.id};}
const app=document.querySelector('#app'),dialog=document.querySelector('#editor');
const prompts=['Which ingredient is genuinely changing the idea, and which is just decoration?','What would make this combination awkward? The friction may be the useful part.','Who would this leave out? Try replacing the audience while keeping the mechanism.','What is the smallest version that somebody could actually try tomorrow?','Keep the problem. Borrow a mechanism from a completely different world.','Which dimension have you treated as fixed without noticing?'];
const current=()=>state.workspaces.find(w=>w.id===state.activeId);
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function save(){const ok=!savePaused&&writeStore(KEY,state);document.querySelectorAll('.save-status').forEach(el=>{el.textContent=ok?'Saved in this browser':savePaused?'Saving paused · export to keep work':'Storage unavailable · export to keep work';el.classList.toggle('error',!ok);});return ok;}
function checkpoint(){undo.push(structuredClone(state));if(undo.length>20)undo.shift();}
function change(fn){const w=structuredClone(current());fn(w);const valid=validateWorkspace(w);checkpoint();state.workspaces[state.workspaces.findIndex(x=>x.id===w.id)]=valid;render();}
function addWorkspace(w){if(state.workspaces.length>=100)throw Error('Keep at most 100 workspaces.');const next=validateWorkspace(w);next.id=uid();checkpoint();state.workspaces.push(next);state.activeId=next.id;dialog.close();render();}
function conceptLabel(c,i){return c.title||`Combination ${i+1}`;}
// Branch tools belong to the shared collection, so both exploration views expose them.
function render(){const focus=document.activeElement;const restore=app.contains(focus)?{id:focus.id,action:focus.dataset.action,mapAction:focus.dataset.mapAction,lineageAction:focus.dataset.lineageAction,key:focus.dataset.id,dimension:focus.dataset.dimension}:null;const w=current(),active=w.concepts.find(c=>c.id===w.activeConceptId);
 app.innerHTML=`${storageNotice?`<div class="storage-notice" role="status"><span>${e(storageNotice)}</span>${recoveryRaw?'<button class="btn small" data-action="recovery">Download recovery copy</button><button class="btn small" data-action="resume-save">Start fresh</button>':savePaused?'<button class="btn small" data-action="reload">Load latest save</button><button class="btn small" data-action="resume-save">Save this tab instead</button>':''}</div>`:''}<section class="intro"><div><p class="eyebrow">Scaffold 02 · Explore possibilities</p><h1>Possibility mixer</h1><p>Combine ingredients. Map what you have explored.<br>Give a promising possibility a job.</p></div><div class="workspace-tools"><label class="sr-only" for="workspace">Workspace</label><select id="workspace">${state.workspaces.map(x=>`<option value="${e(x.id)}" ${x.id===w.id?'selected':''}>${e(x.title)}</option>`).join('')}</select><button class="btn" data-action="new">+ New workspace</button><button class="btn" data-action="export">Export</button><button class="btn quiet" data-action="undo" ${undo.length?'':'disabled'}>Undo</button><span class="save-status">Saved in this browser</span></div></section>
 <section class="question-panel"><div class="section-label">The question<small>Start here. Or edit as you go.</small></div><div class="question-fields"><label class="sr-only" for="workspace-title">Workspace name</label><input id="workspace-title" class="title-input" maxlength="20000" value="${e(w.title)}"><label class="sr-only" for="problem">Your problem or question</label><textarea id="problem" class="problem-input" rows="1" maxlength="20000" placeholder="What would you like to make possible?">${e(w.problem)}</textarea></div></section>
 ${navigation(w)}
 ${w.view==='map'?mapView(w):generator(w)}
 <section class="develop" aria-labelledby="develop-title"><div class="step-heading"><div><h2 id="develop-title">Develop the same concepts</h2><p>A location is a hypothesis about fit. Explain how the idea would actually help.</p></div><span class="muted" style="font-size:12px">${w.concepts.length} kept</span></div>${ancestryTools(w)}${w.concepts.length?`<div class="develop-layout"><div class="concept-list" role="group" aria-label="Kept concepts">${w.concepts.map((c,i)=>`<button class="concept-tab ${c.id===w.activeConceptId?'active':''}" data-action="concept" data-id="${e(c.id)}" aria-pressed="${c.id===w.activeConceptId}"><small>Concept ${String(i+1).padStart(2,'0')}</small><strong>${e(conceptLabel(c,i))}</strong><span>${c.ancestry.parked?'Parked':c.fitNeedsReview?'Review map fit':c.mechanism?'In development':'Ready to develop'}</span></button>`).join('')}</div>${active?conceptEditor(active):''}</div>`:`<div class="empty-develop"><div><h3>Something catches your eye?</h3><p>Keep it, explain how the ingredients work together, then make the smallest test concrete. Kept concepts stay intact when you mix again.</p></div><button class="btn" ${w.view==='map'?'data-map-action="capture-gap"':'data-action="capture"'}>Develop this ${w.view==='map'?'space':'combination'} →</button></div>`}</section>
 ${sourceRecord(w)}
 <aside class="provocation"><strong>Try a different angle</strong><span id="provocation-text">${prompts[promptIndex]}</span><button class="btn small quiet" data-action="prompt">Another prompt ↗</button></aside>`;
 const problem=document.querySelector('#problem');problem.style.height='auto';problem.style.height=problem.scrollHeight+'px';
 if(restore){let candidate=restore.id?document.getElementById(restore.id):[...app.querySelectorAll('[data-action],[data-map-action],[data-lineage-action]')].find(el=>el.dataset.action===restore.action&&el.dataset.mapAction===restore.mapAction&&el.dataset.lineageAction===restore.lineageAction&&el.dataset.id===restore.key&&el.dataset.dimension===restore.dimension);candidate?.focus({preventScroll:true});}
 save();
}
function generator(w){return ` <section aria-labelledby="space-title"><div class="step-heading"><div><h2 id="space-title">01 / Shape the possibility space</h2><p>Pick ingredients directly, or lock a few and mix the rest. The dimensions are yours to change.</p></div><button class="btn small quiet" data-action="add-axis" ${w.dimensions.length>=8?'disabled':''}>+ Dimension</button></div><div class="dimension-board" style="--columns:${w.dimensions.length}">${w.dimensions.map((d,i)=>`<article class="dimension ${d.locked?'locked':''}"><div class="dimension-top"><div class="dimension-name"><span class="dimension-number">${String(i+1).padStart(2,'0')}</span>${e(d.name)}</div><button class="edit-axis" data-action="edit-axis" data-id="${e(d.id)}" aria-label="Edit ${e(d.name)}">Edit</button></div><div class="option-list" role="group" aria-label="${e(d.name)}">${d.options.map(o=>`<button class="option ${o.id===d.selectedId?'selected':''}" aria-pressed="${o.id===d.selectedId}" data-action="pick" data-dimension="${e(d.id)}" data-id="${e(o.id)}"><span class="option-dot" aria-hidden="true"></span>${e(o.label)}</button>`).join('')}</div><button class="lock" data-action="lock" data-id="${e(d.id)}" aria-pressed="${d.locked}"><span aria-hidden="true">${d.locked?'◆':'◇'}</span>${d.locked?'Locked for mixing':'Keep this ingredient'}</button></article>`).join('')}</div>
 <div class="combination"><div><div class="combo-eyebrow">Your current combination</div><p class="combo-line">${ingredients(w).map(i=>`<b>${e(i.label)}</b>`).join('<span class="divider" aria-hidden="true">/</span>')}</p></div><div class="combo-actions"><button class="btn primary" data-action="mix" ${combinationCount(w,true)<2?'disabled':''}>↻ Mix unlocked</button><button class="btn quiet" data-action="capture">Keep &amp; develop →</button></div></div><div class="space-meta"><span><strong>${combinationCount(w).toLocaleString()}</strong> possible combinations · <strong>${combinationCount(w,true).toLocaleString()}</strong> with these locks</span><span>${w.mixCount} mixes explored · ${w.dimensions.filter(d=>d.locked).length} of ${w.dimensions.length} ingredients locked</span></div></section>`;}
function conceptEditor(c){return `<div class="concept-editor"><label class="sr-only" for="concept-title">Concept name</label><input class="concept-title" id="concept-title" data-field="title" maxlength="20000" value="${e(c.title)}" placeholder="Give this idea a name"><details class="ingredients-record"><summary>Original ingredients · kept at capture</summary><div class="ingredients">${c.ingredients.map(i=>`<span class="ingredient"><b>${e(i.dimension)}</b> ${e(i.label)}</span>`).join('')}</div></details><div class="writing-grid">${[['mechanism','How would it work?','Describe an interaction, not just a category of tool.','Someone could…'],['useful','Why could this help?','What becomes easier to see, decide or do?','This would help because…'],['assumption','What are you assuming?','Name the ingredient that may not fit, or the belief to test.','This depends on…'],['experiment','What is the smallest experiment?','Who tries what, and what would you look for?','Try it with…']].map(([key,label,hint,placeholder])=>`<label>${label}<small>${hint}</small><textarea data-field="${key}" maxlength="20000" placeholder="${placeholder}">${e(c[key])}</textarea></label>`).join('')}</div>${ancestryEditor(c)}${fitEditor(current(),c)}<div class="editor-bottom"><span>Ingredients are a snapshot. Your edits save automatically.</span><button class="btn small quiet danger" data-action="delete-concept" data-id="${e(c.id)}">Remove concept</button></div></div>`;}
let returnFocus=null;
function openDialog(html){if(!dialog.open){const el=document.activeElement;returnFocus={id:el.id,action:el.dataset.action,mapAction:el.dataset.mapAction,lineageAction:el.dataset.lineageAction,key:el.dataset.id};}dialog.innerHTML=html;if(!dialog.open)dialog.showModal();dialog.querySelector('input,textarea,button')?.focus();}
function axisDialog(id){coverage.axisDialog(id);}
function newDialog(){openDialog(`<h2>Start a new workspace</h2><p>Your current work stays saved. Choose a starting space, then make it your own.</p><div class="preset-grid">${Object.entries(PRESETS).map(([key,p])=>`<button class="preset-choice" data-action="preset" data-id="${key}"><strong>${e(p.name)}</strong><span>${e(p.problem||'Bring your own question and edit every dimension.')}</span></button>`).join('')}</div><div class="actions"><button class="btn" data-action="import">Import JSON</button><button class="btn" data-action="close">Cancel</button></div>`);}
function exportDialog(){openDialog(`<h2>Take your ideas with you</h2><p>Markdown is ready for your notes. JSON preserves this workspace so you can reopen it here.</p><div class="preset-grid"><button class="preset-choice" data-action="markdown"><strong>Download Markdown</strong><span>The question, dimensions and every developed concept.</span></button><button class="preset-choice" data-action="json"><strong>Download workspace JSON</strong><span>A portable backup with all editable content.</span></button></div><div class="actions"><button class="btn" data-action="import">Import JSON</button><button class="btn" data-action="close">Close</button></div>`);}
function importWorkspace(){const input=document.querySelector('#import-file');input.value='';input.click();}
document.querySelector('#import-file').addEventListener('change',async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>8000000)throw Error('Use a JSON file smaller than 8 MB.');addWorkspace(parseImport(await file.text()));toast('Workspace imported. Existing work is still saved.');}catch(error){toast(`Could not import: ${error.message}`);}});
function act(action,id,button){const w=current();switch(action){case 'recovery':downloadText('possibility-mixer-recovery.json',recoveryRaw,'application/json');break;case 'resume-save':savePaused=false;recoveryRaw=null;storageNotice='';render();toast('This workspace is now saved.');break;case 'reload':location.reload();break;case 'pick':change(w=>{w.dimensions.find(d=>d.id===button.dataset.dimension).selectedId=id;});break;case 'lock':change(w=>{const d=w.dimensions.find(x=>x.id===id);d.locked=!d.locked;});break;case 'mix':{checkpoint();const result=mixWorkspace(w);state.workspaces[state.workspaces.findIndex(x=>x.id===w.id)]=result.workspace;render();toast(result.changed?'A new combination. What could make these ingredients work together?':'Unlock a dimension to mix.');break;}case 'capture':if(w.concepts.length>=100){toast('This workspace has 100 concepts. Export or start a new workspace.');break;}change(w=>{const c=captureConcept(w);w.concepts.push(c);w.activeConceptId=c.id;});document.querySelector('.concept-editor')?.scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('#concept-title')?.focus({preventScroll:true});break;case 'concept':w.activeConceptId=id;render();break;case 'delete-concept':change(w=>{if(hasDescendants(w.concepts,id))throw Error('This concept has descendants. Park it to keep their history.');w.concepts=w.concepts.filter(c=>c.id!==id);w.activeConceptId=w.concepts[0]?.id??null;});toast('Concept removed. Undo brings it back.');break;case 'edit-axis':axisDialog(id);break;case 'add-axis':axisDialog();break;case 'remove-axis':change(w=>{w.dimensions=w.dimensions.filter(d=>d.id!==id);w.history=[];});dialog.close();toast('Dimension removed. Undo brings it back.');break;case 'new':newDialog();break;case 'preset':addWorkspace(createWorkspace(id));break;case 'export':exportDialog();break;case 'markdown':downloadText('possibility-mixer.md',markdown(w),'text/markdown;charset=utf-8');dialog.close();toast('Markdown downloaded.');break;case 'json':downloadText('possibility-mixer.json',JSON.stringify({kind:'mixer',version:1,workspace:w},null,2),'application/json');dialog.close();toast('Workspace downloaded.');break;case 'import':importWorkspace();break;case 'close':dialog.close();break;case 'undo':if(undo.length){state=undo.pop();render();toast('Last change undone.');}break;case 'prompt':promptIndex=(promptIndex+1)%prompts.length;document.querySelector('#provocation-text').textContent=prompts[promptIndex];break;}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button&&!button.disabled)try{act(button.dataset.action,button.dataset.id,button);}catch(error){toast(error.message);}});
let editing=null;
app.addEventListener('focusin',event=>{if(event.target.matches('input,textarea'))editing=null;});
app.addEventListener('input',event=>{
 const w=current(),target=event.target;if(!target.matches('input,textarea'))return;const before=structuredClone(w);
 if(editing!==target){checkpoint();editing=target;}
 if(target.id==='problem'){w.problem=target.value;target.style.height='auto';target.style.height=target.scrollHeight+'px';}
 else if(target.id==='workspace-title'){w.title=target.value;document.querySelector('#workspace').selectedOptions[0].textContent=w.title||'Untitled workspace';}
 else if(target.id==='gap-reason'){const g=gap(w);g.reason=target.value;w.map.notes[noteKey(g.coordinates)]=g;const summary=app.querySelector('.all-gaps summary');if(summary)summary.textContent=`All examined spaces · ${Object.keys(w.map.notes).length}`;}
 else if(['title','mechanism','useful','assumption','experiment','fit','changed','reason'].includes(target.dataset.field)){
  const c=w.concepts.find(x=>x.id===w.activeConceptId);if(c)c[target.dataset.field]=target.value;
  const tab=document.querySelector('.concept-tab.active');if(tab){tab.querySelector('strong').textContent=conceptLabel(c,w.concepts.indexOf(c));tab.querySelector('span').textContent=c.fitNeedsReview?'Review map fit':c.mechanism?'In development':'Ready to develop';}
  for(const card of app.querySelectorAll('.map-idea'))if(card.dataset.dragId===c.id){card.querySelector('.idea-title').textContent=conceptLabel(c,w.concepts.indexOf(c));const p=card.querySelector('p');if(p)p.textContent=c.mechanism;else if(c.mechanism){const text=document.createElement('p');text.textContent=c.mechanism;card.append(text);}}
 }
 try{assertPortable(w);}catch(error){Object.assign(w,before);render();toast(error.message);return;}
 save();document.querySelector('[data-action="undo"]').disabled=!undo.length;
});
app.addEventListener('change',event=>{if(event.target.id==='workspace'){state.activeId=event.target.value;render();}});
dialog.addEventListener('close',()=>{if(!returnFocus)return;const ref=returnFocus;const el=ref.id?document.getElementById(ref.id):[...app.querySelectorAll('[data-action],[data-map-action],[data-lineage-action]')].find(x=>x.dataset.action===ref.action&&x.dataset.mapAction===ref.mapAction&&x.dataset.lineageAction===ref.lineageAction&&x.dataset.id===ref.key);el?.focus({preventScroll:true});});
dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close();}});
addEventListener('storage',event=>{if(event.key===KEY&&event.newValue!==JSON.stringify(state)){savePaused=true;storageNotice='Another tab changed the saved work. Saving is paused so this tab cannot overwrite it.';render();}});
wireAncestry({app,dialog,current,change,openDialog,render,toast});
const coverage=wireCoverage({app,dialog,current,change,openDialog,addWorkspace,render,save,toast,checkpoint});
render();
if(document.modelContext?.registerTool){const controller=new AbortController();const tools=[{name:'read_possibility_workspace',title:'Read possibility workspace',description:'Read the current question, dimensions, selected ingredients and kept concepts.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async(input)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object.');return{content:[{type:'text',text:JSON.stringify(current())}]};}},{name:'mix_possibility_ingredients',title:'Mix unlocked ingredients',description:'Generate a new combination while preserving locked ingredients. This updates the visible workspace.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async(input)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object.');act('mix');return{content:[{type:'text',text:JSON.stringify(ingredients(current()))}]};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}addEventListener('pagehide',()=>controller.abort(),{once:true});}
